package fr.jmproduction.pocketdoor.block;
import fr.jmproduction.pocketdoor.Content; import fr.jmproduction.pocketdoor.network.ModMessages;
import net.minecraft.core.BlockPos; import net.minecraft.network.chat.Component; import net.minecraft.world.InteractionHand; import net.minecraft.world.InteractionResult; import net.minecraft.world.entity.player.Player; import net.minecraft.world.item.ItemStack; import net.minecraft.world.level.Level; import net.minecraft.world.level.block.Block; import net.minecraft.world.level.block.state.BlockState; import net.minecraft.world.level.block.state.StateDefinition; import net.minecraft.world.level.block.state.properties.BooleanProperty; import net.minecraft.world.phys.BlockHitResult;
public final class CartostellaireBlock extends Block { public static final BooleanProperty ACTIVATED=BooleanProperty.create("activated"); public CartostellaireBlock(Properties p){super(p);registerDefaultState(stateDefinition.any().setValue(ACTIVATED,false));} @Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(ACTIVATED);}@Override public InteractionResult use(BlockState s,Level l,BlockPos p,Player pl,InteractionHand h,BlockHitResult hit){ItemStack st=pl.getItemInHand(h);if(st.is(Content.PURIFIED_TERTARIUM_CRYSTAL)&&!s.getValue(ACTIVATED)){if(!l.isClientSide){l.setBlock(p,s.setValue(ACTIVATED,true),3);if(!pl.getAbilities().instabuild)st.shrink(1);pl.displayClientMessage(Component.literal("Le Cartostellaire peut maintenant s'activer"),true);}return InteractionResult.sidedSuccess(l.isClientSide);}if(!s.getValue(ACTIVATED)){if(!l.isClientSide)pl.displayClientMessage(Component.literal("Le Cartostellaire n'as pas assez d'énergie pour s'activer"),true);return InteractionResult.sidedSuccess(l.isClientSide);}if(st.isEmpty()){if(!l.isClientSide)ModMessages.sendCartostellaireStart((net.minecraft.server.level.ServerPlayer)pl,p);return InteractionResult.sidedSuccess(l.isClientSide);}return InteractionResult.PASS;}}
